parameters.jsCode:
const raw = $input.first().json;
const rawBody = raw.body || raw;
const payload = rawBody.data || rawBody;

const employeeName = payload.employeeName || payload.fullName || 'Nhân sự';
const userId = payload.userId || 'N/A';
const department = payload.departmentName || payload.department || 'Phòng Ban';
const stressDays = payload.stressDays || 1;
const latestFeedback = payload.latestFeedback || '(Không có ghi chú thêm)';
const reviewPortalUrl = payload.reviewPortalUrl || 'http://localhost:5173/admin/burnout-alerts';
const fromEmail = payload.fromEmail || 'quocthangngo2006@gmail.com';
const hrEmail = payload.hrEmail || 'quocthangngo2006@gmail.com';

let severityBadge = '🟡 VỪA (MEDIUM)';
let severityColor = '#eab308';
let urgentLevel = 'Cảnh báo theo dõi';

if (stressDays >= 3) {
  severityBadge = '🔴 KHẨN CẤP (CRITICAL - NGUY CƠ NGHỈ VIỆC CAO)';
  severityColor = '#ef4444';
  urgentLevel = 'Yêu cầu Trưởng phòng can thiệp 1-on-1 trong 24 giờ!';
} else if (stressDays >= 2) {
  severityBadge = '🟠 CAO (HIGH - QUÁ TẢI SPRINT)';
  severityColor = '#f97316';
  urgentLevel = 'Khuyến nghị rà soát và san sẻ bớt task tồn đọng';
}

const htmlTemplate = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f8fafc; margin: 0; padding: 20px; }
    .container { max-width: 620px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.08); border-top: 5px solid ${severityColor}; }
    .header { background: #ffffff; color: #0f172a; padding: 25px 30px; border-bottom: 1px solid #e2e8f0; }
    .header h1 { margin: 0; font-size: 20px; color: #dc2626; display: flex; align-items: center; gap: 8px; }
    .content { padding: 30px; color: #334155; line-height: 1.6; }
    .badge { display: inline-block; background: ${severityColor}; color: #ffffff; padding: 4px 12px; border-radius: 20px; font-size: 13px; font-weight: 700; margin-bottom: 15px; }
    .alert-card { background: #fef2f2; border: 1px solid #fee2e2; border-radius: 8px; padding: 18px; margin: 15px 0; }
    .item { margin: 8px 0; font-size: 14px; }
    .quote { background: #ffffff; border-left: 3px solid #dc2626; padding: 12px 16px; margin: 15px 0; font-style: italic; color: #475569; border-radius: 0 6px 6px 0; }
    .actions { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 18px; margin-top: 20px; }
    .btn { display: inline-block; background: #dc2626; color: #ffffff !important; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: 600; text-align: center; margin-top: 10px; }
    .footer { text-align: center; font-size: 12px; color: #94a3b8; padding: 20px; border-top: 1px solid #e2e8f0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🚨 CẢNH BÁO NGUY CƠ KIỆT SỨC (BURNOUT RISK)</h1>
      <p style="margin: 4px 0 0 0; color: #64748b; font-size: 14px;">Hệ thống Giám sát Hạnh phúc & Sức khỏe Tinh thần Đội ngũ</p>
    </div>
    <div class="content">
      <div class="badge">${severityBadge}</div>
      <p>Kính gửi <strong>Trưởng Phòng Ban & Giám Đốc Nhân Sự</strong>,</p>
      <p>Hệ thống AI vừa phát hiện dấu hiệu quá tải tinh thần nghiêm trọng từ nhân sự trực thuộc quản lý của bạn:</p>

      <div class="alert-card">
        <div class="item">👤 <strong>Nhân viên:</strong> ${employeeName} (Mã nhân sự: #${userId})</div>
        <div class="item">🏢 <strong>Phòng ban:</strong> ${department}</div>
        <div class="item">⏱️ <strong>Số ngày stress liên tiếp:</strong> <span style="color: #dc2626; font-weight: 700;">${stressDays} ngày</span></div>
        <div class="item">⚡ <strong>Mức độ khẩn cấp:</strong> ${urgentLevel}</div>
      </div>

      <p><strong>Lời nhắn phản hồi check-in từ nhân viên:</strong></p>
      <div class="quote">"${latestFeedback}"</div>

      <div class="actions">
        <div style="font-weight: 700; color: #0f172a; margin-bottom: 8px;">🎯 HÀNH ĐỘNG KHUYẾN NGHỊ NGAY HÔM NAY:</div>
        <ul style="margin: 0; padding-left: 20px; font-size: 14px;">
          <li>Đặt lịch hẹn trao đổi 1-on-1 trong 24 giờ để lắng nghe tâm tư thực tế.</li>
          <li>Rà soát lại danh sách task trong Sprint, hỗ trợ giảm tải hoặc san sẻ công việc.</li>
          <li>Xem xét đề xuất cho nhân viên nghỉ bù hoặc sử dụng 1 ngày Mental Health Day.</li>
        </ul>
        <div style="text-align: center;">
          <a href="${reviewPortalUrl}" class="btn" target="_blank">🔍 Mở Bảng Điều Khiển Can Thiệp 1-on-1</a>
        </div>
      </div>
    </div>
    <div class="footer">
      © 2026 Enterprise Corporation. Cảnh báo tự động phát ra từ n8n Automation Engine.
    </div>
  </div>
</body>
</html>
`;

const telegramAlert = `🚨 <b>CẢNH BÁO NGUY CƠ KIỆT SỨC (BURNOUT ALERT)</b>\n\n` +
  `• <b>Nhân sự:</b> ${employeeName} (ID: #${userId})\n` +
  `• <b>Phòng ban:</b> ${department}\n` +
  `• <b>Mức độ:</b> <b>${severityBadge}</b>\n` +
  `• <b>Số ngày stress liên tục:</b> <code>${stressDays} ngày</code>\n` +
  `• <b>Lời nhắn:</b> <i>"${latestFeedback}"</i>\n\n` +
  `⚡ <b>Yêu cầu hành động:</b> ${urgentLevel}\n` +
  `👉 <a href="${reviewPortalUrl}">Mở trang can thiệp 1-on-1 trên HR Portal</a>`;

return {
  json: {
    fromEmail: fromEmail,
    hrEmail: hrEmail,
    employeeName: employeeName,
    userId: userId,
    department: department,
    stressDays: stressDays,
    severityBadge: severityBadge,
    telegramChatId: payload.telegramChatId || payload.chatId,
    emailSubject: `[KHẨN CẤP] Cảnh báo nguy cơ kiệt sức đối với ${employeeName} (${department})`,
    emailHtml: htmlTemplate,
    telegramAlert: telegramAlert
  }
};
